INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/031e1060ccf5b9f107eacfa64c5b054c3042e300/content/books/zizhi-tongjian/vol-293/year-0957/part-03/sources/library/jiuwudaishi-117-april-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002769；EPUB电子本，纸本及异文待核", "id": "e7928401-9390-531d-8c82-748699a759cf"}, {"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/031e1060ccf5b9f107eacfa64c5b054c3042e300/content/books/zizhi-tongjian/vol-293/year-0957/part-03/sources/library/jiuwudaishi-117-may-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002770；EPUB电子本，纸本及异文待核", "id": "f79aa59b-43cc-5d9a-8058-affd6150e940"}, {"title": "旧五代史·卷一百二十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/031e1060ccf5b9f107eacfa64c5b054c3042e300/content/books/zizhi-tongjian/vol-293/year-0957/part-03/sources/library/jiuwudaishi-129-liurenshan-death/source.txt", "note": "《旧五代史》卷一百二十九，段落 jiu-wudaishi-205deb4a7860-p003043；EPUB电子本，纸本及异文待核", "id": "d2b33fd2-70e3-5725-9099-0894afa3e4b0"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/031e1060ccf5b9f107eacfa64c5b054c3042e300/content/books/zizhi-tongjian/vol-293/year-0957/part-03/sources/library/tongjian-293-957-shouchun-aftermath/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003482；电子底本待考，分段待核", "id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"title": "新五代史·卷三十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/031e1060ccf5b9f107eacfa64c5b054c3042e300/content/books/zizhi-tongjian/vol-293/year-0957/part-03/sources/library/xinwudaishi-32-liurenshan-death/source.txt", "note": "《新五代史》卷三十二，段落 xin-wudaishi-b08f244b9241-p001164；EPUB电子本，纸本及异文待核", "id": "ad6fea00-bf22-5ce4-910f-53e97d74e681"}, {"title": "新五代史·卷三十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/031e1060ccf5b9f107eacfa64c5b054c3042e300/content/books/zizhi-tongjian/vol-293/year-0957/part-03/sources/library/xinwudaishi-32-liurenshan-honors/source.txt", "note": "《新五代史》卷三十二，段落 xin-wudaishi-b08f244b9241-p001165；EPUB电子本，纸本及异文待核", "id": "7f8399ae-dd3b-5809-a9b1-1ccd41621f4b"}, {"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/876887409d392e3dbf7c3028c1ed5b981c9251c0/content/books/zizhi-tongjian/vol-293/year-0957/part-02/sources/library/jiuwudaishi-117-march-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002768；EPUB电子本，纸本及异文待核", "id": "741cd85e-1fa7-5490-9361-5f55a2c4be66"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "刘崇赞", "aliases": ["劉崇讚", "劉崇讃", "崇讚", "崇讃"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘仁赡之子。新旧五代史记父亲去世后获任怀州刺史，名字作崇讚或崇讃，本站用简体崇赞。与主书崇让缺少同人证据，暂分别保存；不据此断言两人长幼。", "biography": null, "status": "draft", "id": "004e7b78-f8b7-5e10-bac9-2f467db3f1ea"}, {"name": "杨信", "aliases": ["楊信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周右羽林统军。957年寿春受降后获任忠正节度使、同平章事。生卒年未载。", "biography": null, "status": "draft", "id": "ca7cacb7-78f6-5378-9a39-84ea7c60adc4"}, {"name": "韩伦", "aliases": ["韓倫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "韩令坤之父，前许州司马。957年因干预陈州政务、贪污受讼获免死流沙门岛。后来赦还居洛阳、与权贵父辈游处，具体赦还年份未载。", "biography": null, "status": "draft", "id": "73c38479-8433-5a0f-8bb5-7b364b301ae1"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "柴守礼", "aliases": ["柴守禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "柴荣的父亲，也是郭威妻子柴氏的兄长。《资治通鉴》和新旧五代史都记其父子身份；本段没有记其950年官职和生卒年。", "biography": null, "status": "draft", "id": "1f68967c-4559-5c4a-b49e-dda40ce4dd8e"}, {"name": "尹日就", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周左谏议大夫。《旧五代史》记957年寿州受降后，受命前往寿州开仓赈济饥民。生卒年未载。", "biography": null, "status": "draft", "id": "ed2f6a77-6008-5d03-a738-90913d39eeaa"}, {"name": "孙延希", "aliases": ["孫延希"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宦官、内供奉官。957年督修永福殿，柴荣看到役夫食具简陋，大怒将其斩于市。没有据此补出克扣金额或具体贪污案。", "biography": null, "status": "draft", "id": "02956dad-d329-56a9-9842-181a065b14d9"}, {"name": "董延勋", "aliases": ["董延勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周御厨使。《旧五代史》记957年四月与孙延希督工事件相关，被柴荣停职。生卒年未载。", "biography": null, "status": "draft", "id": "7e2364e9-ef67-5b04-bf22-c4d8678f1138"}, {"name": "张皓", "aliases": ["張皓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周御厨副使。957年四月与孙延希督工事件相关，被停职。生卒年未载。", "biography": null, "status": "draft", "id": "35743180-11de-5be9-a092-e0e36ffaf0fd"}, {"name": "卢继升", "aliases": ["盧繼升"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周武德副使。957年四月与孙延希督工事件相关，被停职。生卒年未载。", "biography": null, "status": "draft", "id": "131306de-19a2-5b24-840d-8704a22d9cfe"}, {"name": "萧知远", "aliases": ["蕭知遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周怀恩军指挥使。957年四月受命与八百余将士西还。怀恩军来自此前秦凤战役俘获的后蜀兵，生卒年未载。", "biography": null, "status": "draft", "id": "218f658a-18eb-54bd-bcc8-042a967bcda9"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "后周迁寿州治所到下蔡，赦州境罪犯", "start_year": 957, "end_year": 957, "time_original": "957年三月庚戌", "dynasty": "五代十国", "description": "后周迁寿州治所到下蔡，赦州境罪犯。", "phases": [], "location_name": "寿州、下蔡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2d793a69-cf05-5a7f-8264-2001633db979"}, {"title": "后周召山林中州民复业，禁报复仇讼并征求政令改进", "start_year": 957, "end_year": 957, "time_original": "957年三月庚戌赦令所记", "dynasty": "五代十国", "description": "后周召受南唐文书、聚在山林的州民恢复生业，不追究此事；对曾经杀伤，不许相互报复或再诉。旧政令不便民者，令州府逐项上奏，不把征求意见写成每条旧令已立即废除。", "phases": [], "location_name": "寿州山林及州境", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cbe798bf-3676-5d09-aa16-1cec48ae9278"}, {"title": "后周免寿州近城本年租税，安排赎回被掳亲属、掩埋战场遗骸", "start_year": 957, "end_year": 957, "time_original": "《旧五代史》957年三月庚戌诏令", "dynasty": "五代十国", "description": "《旧五代史》补记：寿州距城五十里内免本年夏秋租税；百姓可认回用兵以来被掳亲属，官府给钱物赎回，不限远近；收拾掩埋战场暴露骸骨。这是诏令安排，未提供执行人数、赎价和完成日期。", "phases": [], "location_name": "寿州距城五十里内及相关战场", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "617309ad-abde-5004-aa0d-b2c95bfe4f5a"}, {"title": "柴荣授刘仁赡天平节度使兼中书令，称许其守节", "start_year": 957, "end_year": 957, "time_original": "957年三月辛亥", "dynasty": "五代十国", "description": "柴荣授刘仁赡天平节度使兼中书令，称许其守节。", "phases": [], "location_name": "后周朝廷、寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f1932c87-7b37-51b3-8409-677f2ab685dc"}, {"title": "刘仁赡去世，后周追封、南唐赠太师", "start_year": 957, "end_year": 957, "time_original": "《资治通鉴》957年三月辛亥去世；追赠具体日未载", "dynasty": "五代十国", "description": "《通鉴》记刘仁赡在辛亥获任当天去世，后周追赐爵号，李璟闻讯亦赠太师。底本爵号作“彭城郡主”，新旧五代史均作“彭城郡王”，作为字形问题注明，不把异常字当作女子身份。", "phases": [], "location_name": "寿州及后周、南唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0363c160-be55-58a6-bd50-0066063b2228"}, {"title": "刘仁赡去世后，刘崇赞获任怀州刺史", "start_year": null, "end_year": null, "time_original": "刘仁赡957年去世以后，具体授任年日未载", "dynasty": "五代十国", "description": "刘仁赡去世后，刘崇赞获任怀州刺史。", "phases": [], "location_name": "怀州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9d858542-6a0e-5154-8f59-dc6f24eaf463"}, {"title": "柴荣将清淮军改为忠正军，任杨信为节度使", "start_year": 957, "end_year": 957, "time_original": "957年三月刘仁赡去世条所记，独立改号日未载", "dynasty": "五代十国", "description": "柴荣将清淮军改为忠正军，任杨信为节度使。", "phases": [], "location_name": "寿州忠正军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dea8e710-23b3-527e-b0f9-5309b06d2862"}, {"title": "韩伦干预陈州政务、贪污受讼，韩令坤屡次求情", "start_year": null, "end_year": null, "time_original": "957年三月癸丑处分之前，具体各次行为日未载", "dynasty": "五代十国", "description": "韩伦干预陈州政务、贪污受讼，韩令坤屡次求情。", "phases": [], "location_name": "陈州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5a50c4e4-a81a-5e13-8184-bcaf33fddd4b"}, {"title": "柴荣免韩伦死罪，流放沙门岛", "start_year": 957, "end_year": 957, "time_original": "957年三月癸丑", "dynasty": "五代十国", "description": "柴荣免韩伦死罪，流放沙门岛。", "phases": [], "location_name": "陈州至沙门岛", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5bced441-8861-55cb-9e3b-fd4e5230fa9b"}, {"title": "韩伦后来获赦还，在洛阳与权贵父辈恃势游处", "start_year": null, "end_year": null, "time_original": "957年流放以后，具体赦还和洛阳活动年份未载", "dynasty": "五代十国", "description": "韩伦后来获赦还，居洛阳，与致仕的柴守礼及王溥、王晏、王彦超之父游处，恃势放纵，史书称洛阳人畏惧、称他们为十阿父。所列不是十个人的完整实名名单，不补造其余姓名，也不把这些后来活动全定957年。", "phases": [], "location_name": "洛阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d82153b5-94c0-5182-8a15-3f2924ac63a8"}, {"title": "柴荣作为郭威嗣子，朝廷以元舅礼遇其生父柴守礼", "start_year": null, "end_year": null, "time_original": "柴荣成为郭威嗣子及在位期间的概述，具体优给日未载", "dynasty": "五代十国", "description": "柴荣作为郭威嗣子，朝廷以元舅礼遇其生父柴守礼。", "phases": [], "location_name": "洛阳与后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4ff58685-394d-56a1-88de-1856a7311cf8"}, {"title": "柴守礼因小忿杀人，官府不敢查，柴荣知而不问", "start_year": null, "end_year": null, "time_original": "柴荣在位期间旧事，具体年日未载", "dynasty": "五代十国", "description": "柴守礼因小忿杀人，官府不敢查，柴荣知而不问。", "phases": [], "location_name": "洛阳，具体案发处未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "462d27be-49fd-5771-8a0c-769d8d475825"}, {"title": "后周命开寿州仓赈济饥民", "start_year": 957, "end_year": 957, "time_original": "957年三月寿州受降以后、丙辰北还以前，具体下诏日未载", "dynasty": "五代十国", "description": "后周命开寿州仓赈济饥民。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "696dae1a-12ee-5e24-96af-a3f10c060b9f"}, {"title": "柴荣由淮南北还，四月抵大梁", "start_year": 957, "end_year": 957, "time_original": "957年三月丙辰北还，四月己巳抵大梁", "dynasty": "五代十国", "description": "柴荣由淮南北还，四月抵大梁。", "phases": [], "location_name": "下蔡至大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "240d8073-a71f-52bc-a4ce-d25b6da806ce"}, {"title": "柴荣命修永福殿，孙延希督工", "start_year": 957, "end_year": 957, "time_original": "957年四月丁丑视察之前，具体开工日未载", "dynasty": "五代十国", "description": "柴荣命修永福殿，孙延希督工。", "phases": [], "location_name": "永福殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c86bf465-d13c-57f3-a5bc-a9c20d55e191"}, {"title": "柴荣见役夫食具简陋，怒斩督工孙延希", "start_year": 957, "end_year": 957, "time_original": "957年四月丁丑", "dynasty": "五代十国", "description": "柴荣视察永福殿，见役夫以简陋勺具、瓦器进食，大怒，将督工孙延希斩于市场。原文“削柿为匕”的字形和名物待校，不写成吃柿子，也不补出贪污金额或克扣口粮案。", "phases": [], "location_name": "永福殿及京城市场", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "01ce0685-ec5e-5360-a88b-5bbf7f1225e0"}, {"title": "孙延希督工事件后，董延勋、张皓、卢继升被停职", "start_year": 957, "end_year": 957, "time_original": "《旧五代史》957年四月丁丑", "dynasty": "五代十国", "description": "孙延希督工事件后，董延勋、张皓、卢继升被停职。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "eef96cd6-46c3-5715-97fa-3c78f259e459"}, {"title": "后周以秦凤战役中的数千后蜀兵组成怀恩军", "start_year": 955, "end_year": 955, "time_original": "955年秦凤战役以后，具体编军日未载", "dynasty": "五代十国", "description": "后周以秦凤战役中的数千后蜀兵组成怀恩军。", "phases": [], "location_name": "秦、凤至后周军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3a97f933-8966-5bc3-83fa-7267686b4a8f"}, {"title": "柴荣遣萧知远等怀恩军八百余将士西还", "start_year": 957, "end_year": 957, "time_original": "957年四月乙亥", "dynasty": "五代十国", "description": "柴荣遣萧知远等怀恩军八百余将士西还。", "phases": [], "location_name": "后周向西返程，终点本句未明", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a5377fe4-bc9c-557d-9879-480825075925"}, {"title": "李谷带病入见求辞禄位，柴荣免拜赐座而不准", "start_year": 957, "end_year": 957, "time_original": "《资治通鉴》957年四月壬午；《旧五代史》请退条记丙子", "dynasty": "五代十国", "description": "李谷带病入见求辞禄位，柴荣免拜赐座而不准。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f7cab9a8-78ea-543f-bd0a-8a657d3f3a17"}, {"title": "后周将南唐降卒编为六军三十指挥，号怀德军", "start_year": 957, "end_year": 957, "time_original": "957年四月甲申", "dynasty": "五代十国", "description": "后周将南唐降卒编为六军三十指挥，号怀德军。", "phases": [], "location_name": "后周降卒编组地未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "aee2350b-7d97-5266-9e91-77e0736cf80b"}, {"title": "后周疏通汴水北入五丈河，齐鲁舟船可达大梁", "start_year": 957, "end_year": 957, "time_original": "957年四月乙酉下诏，具体工程完成日未载", "dynasty": "五代十国", "description": "后周下令疏通汴水，使其向北接五丈河。《通鉴》随后概述齐、鲁舟船因此能通到大梁；不把后来通航效果全部固定为下诏当天，不补现代河道坐标。", "phases": [], "location_name": "汴水、五丈河、齐鲁至大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b9e99865-a588-5d62-a123-a03439e230d3"}, {"title": "赵匡胤领义成节度使", "start_year": 957, "end_year": 957, "time_original": "957年五月丁酉", "dynasty": "五代十国", "description": "赵匡胤领义成节度使。", "phases": [], "location_name": "义成军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b0045b15-9dd7-574a-a8a8-3ba0a764020d"}]'::jsonb)
