INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "后周迁寿州治所到下蔡，赦州境罪犯。", "citation": "卷293·显德四年（957年三月至五月及相关追述）·zztj-v293-y0957-p015·原文件第79行", "note": "原文：庚戌，徙寿州治下蔡，赦州境死罪以下。；核对说明：迁州治不同于全体居民搬迁；赦限州境，不扩大为全国大赦。", "status": "draft", "id": "e1fe0081-b174-5d22-8cf9-c8cea37a8d30", "subject_id": "2d793a69-cf05-5a7f-8264-2001633db979", "source_id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "957年三月庚戌", "citation": "卷293·显德四年（957年三月至五月及相关追述）·zztj-v293-y0957-p015·原文件第79行", "note": "原文：庚戌，徙寿州治下蔡，赦州境死罪以下。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "765c3248-652e-5d45-9fcc-c08e3c6ca290", "subject_id": "2d793a69-cf05-5a7f-8264-2001633db979", "source_id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：迁州治并颁赦令。", "citation": "卷293·显德四年（957年三月至五月及相关追述）·zztj-v293-y0957-p015·原文件第79行", "note": "原文：庚戌，徙寿州治下蔡，赦州境死罪以下。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "aba26511-96cf-56b7-a37f-9ed7e22ebe2e", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：迁州治并颁赦令。", "citation": "卷293·显德四年（957年三月至五月及相关追述）·zztj-v293-y0957-p015·原文件第79行", "note": "原文：庚戌，徙寿州治下蔡，赦州境死罪以下。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "f65abc0b-2b61-5120-88a4-f6b49be124b5", "subject_id": "0df5db40-c923-5c4a-a940-e79914c089fe", "source_id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》补记旧州治改为寿春县。", "citation": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002768；EPUB电子本，纸本及异文待核", "note": "原文：庚戌，詔移壽州於下蔡，以故壽州為壽春縣。；核对说明：地名行政调整保持原称，不推现代疆界或全城人口迁移。", "status": "draft", "id": "7652ef6f-79da-5aac-bb95-ac207d009929", "subject_id": "2d793a69-cf05-5a7f-8264-2001633db979", "source_id": "741cd85e-1fa7-5490-9361-5f55a2c4be66"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》记寿州局部赦令，限本月二十一日以前过犯。", "citation": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002768；EPUB电子本，纸本及异文待核", "note": "原文：是日，曲赦壽州管內見禁罪人，自今月二十一日已前，凡有過犯，並從釋放。；核对说明：限定时间按原纪月保留，不能把之后犯罪或别州全算赦免。", "status": "draft", "id": "5e6cd88b-8b13-5eff-ae62-72fd72e1f521", "subject_id": "2d793a69-cf05-5a7f-8264-2001633db979", "source_id": "741cd85e-1fa7-5490-9361-5f55a2c4be66"}, {"subject_table": "event", "field_path": "description", "claim_text": "后周召受南唐文书、聚在山林的州民恢复生业，不追究此事；对曾经杀伤，不许相互报复或再诉。旧政令不便民者，令州府逐项上奏，不把征求意见写成每条旧令已立即废除。", "citation": "卷293·显德四年（957年三月至五月及相关追述）·zztj-v293-y0957-p015·原文件第79行", "note": "原文：州民受唐文书聚山林者，并召令复业，勿问罪。有尝为其杀伤者，毋得仇讼。曏日政令有不便于民者，令本州条奏。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "c5d5d27a-2ffe-535f-9a7a-f1b4b4fa7bc3", "subject_id": "cbe798bf-3676-5d09-aa16-1cec48ae9278", "source_id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "957年三月庚戌赦令所记", "citation": "卷293·显德四年（957年三月至五月及相关追述）·zztj-v293-y0957-p015·原文件第79行", "note": "原文：州民受唐文书聚山林者，并召令复业，勿问罪。有尝为其杀伤者，毋得仇讼。曏日政令有不便于民者，令本州条奏。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "90ae905a-1b5a-5204-9357-3d4121f1c253", "subject_id": "cbe798bf-3676-5d09-aa16-1cec48ae9278", "source_id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同记不问聚山林罪、禁止互仇再诉。", "citation": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002768；EPUB电子本，纸本及异文待核", "note": "原文：自來百姓，有曾受江南文字聚集山林者，並不問罪。如有曾相傷害者，今後不得更有相仇及經官論訴。；核对说明：针对战时相关情节，不推广为一切未来杀伤均免责。", "status": "draft", "id": "bc52848c-2474-5bdb-ab65-cd70ea3dfee9", "subject_id": "cbe798bf-3676-5d09-aa16-1cec48ae9278", "source_id": "741cd85e-1fa7-5490-9361-5f55a2c4be66"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》补记：寿州距城五十里内免本年夏秋租税；百姓可认回用兵以来被掳亲属，官府给钱物赎回，不限远近；收拾掩埋战场暴露骸骨。这是诏令安排，未提供执行人数、赎价和完成日期。", "citation": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002768；EPUB电子本，纸本及异文待核", "note": "原文：壽州管界去城五十里內，放今年秋夏租稅。自來百姓，有曾受江南文字聚集山林者，並不問罪。如有曾相傷害者，今後不得更有相仇及經官論訴。自用兵已來，被擄卻骨肉者，不計遠近，並許本家識認，官中給物收贖。曾經陣敵處所暴露骸骨，並仰收拾埋瘞。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "5bacdac4-7ecf-5dfa-be34-e252639db906", "subject_id": "617309ad-abde-5004-aa0d-b2c95bfe4f5a", "source_id": "741cd85e-1fa7-5490-9361-5f55a2c4be66"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《旧五代史》957年三月庚戌诏令", "citation": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002768；EPUB电子本，纸本及异文待核", "note": "原文：壽州管界去城五十里內，放今年秋夏租稅。自來百姓，有曾受江南文字聚集山林者，並不問罪。如有曾相傷害者，今後不得更有相仇及經官論訴。自用兵已來，被擄卻骨肉者，不計遠近，並許本家識認，官中給物收贖。曾經陣敵處所暴露骸骨，並仰收拾埋瘞。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ad504c11-e79b-534f-a942-d22974f0e8a1", "subject_id": "617309ad-abde-5004-aa0d-b2c95bfe4f5a", "source_id": "741cd85e-1fa7-5490-9361-5f55a2c4be66"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣授刘仁赡天平节度使兼中书令，称许其守节。", "citation": "卷293·显德四年（957年三月至五月及相关追述）·zztj-v293-y0957-p015·原文件第79行", "note": "原文：辛亥，以刘仁赡为天平节度使兼中书令，制辞略曰：“尽忠所事，抗节无亏，前代名臣，几人堪比！朕之伐叛，得尔为多。”；核对说明：制书赞誉是柴荣评价，不改写成刘此前为后周效忠。", "status": "draft", "id": "fa5abbd1-8b46-50f0-9d60-5b6811e89ad1", "subject_id": "f1932c87-7b37-51b3-8409-677f2ab685dc", "source_id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "957年三月辛亥", "citation": "卷293·显德四年（957年三月至五月及相关追述）·zztj-v293-y0957-p015·原文件第79行", "note": "原文：辛亥，以刘仁赡为天平节度使兼中书令，制辞略曰：“尽忠所事，抗节无亏，前代名臣，几人堪比！朕之伐叛，得尔为多。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "49cd5bd1-859f-5db9-9424-e9a9d355e331", "subject_id": "f1932c87-7b37-51b3-8409-677f2ab685dc", "source_id": "8966d44b-3286-5854-bbb7-4ab8b65c666e"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：授官并在制书中赞其尽忠。", "ci